parameters.text:
=Классифицируй GitHub Issue на основе следующих данных:

Title: {{ $json.title }}
Body: {{ $json.body ?? '' }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": ["bug", "task", "feature", "unknown"],
      "description": "Тип Issue; unknown, если тип определить нельзя"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Уверенность в классификации от 0 до 1"
    }
  },
  "required": ["type", "confidence"],
  "additionalProperties": false
}

parameters.jsCode:
const result = $json.output;
const types = ['bug', 'task', 'feature', 'unknown'];
if (!result || !types.includes(result.type) || !Number.isFinite(result.confidence) || result.confidence < 0 || result.confidence > 1) {
  return { json: { type: 'unknown', confidence: 0 } };
}
return { json: { type: result.type, confidence: result.confidence } };
